# ---------- lingua ----------
def lingua_italiana():
    try:
        return (ctypes.windll.kernel32.GetUserDefaultUILanguage() & 0x3FF) == 0x10
    except (AttributeError, OSError):
        return (locale.getlocale()[0] or "").lower().startswith("it")


