def T(chiave):
    return TESTI[chiave][0 if IT else 1]


# ---------- utilita ----------
def punti(stringa):
    return [tuple(float(v) for v in p.split(",")) for p in stringa.split()]


def hex_to_rgb(h):
    h = h.lstrip("#")
    return tuple(int(h[i:i + 2], 16) for i in (0, 2, 4))


def rgb_to_hex(rgb):
    out = "#{:02x}{:02x}{:02x}".format(*(max(2, min(255, int(v))) for v in rgb))
    return "#020202" if out == TRASPARENTE else out


def mescola(c1, c2, t):
    a, b = hex_to_rgb(c1), hex_to_rgb(c2)
    return tuple(x + (y - x) * t for x, y in zip(a, b))


class ScreenTopper:
    def __init__(self, root):
        self.root = root
        self.cfg = self.carica_config()
        self.sfarfallio = tk.BooleanVar(value=self.cfg.get("sfarfallio", True))
        self.intensita = tk.IntVar(value=self.cfg.get("intensita", 40))
        self.mostra_guida = tk.BooleanVar(value=False)
        # bordo extra (mm) attorno a ogni foro: copre piccoli errori di allineamento
        self.bordo = tk.DoubleVar(value=min(BORDO_MAX, self.cfg.get("bordo", BORDO_DEFAULT)))
        effetto = self.cfg.get("effetto", "candela")
        self.effetto = effetto if effetto in EFFETTI else "candela"
        self.effetto_var = tk.StringVar(value=T(self.effetto))
        self.ogni = tk.IntVar(value=self.cfg.get("ogni", 60))
        nome = self.cfg.get("modello")
        self.modello_var = tk.StringVar(value=nome if nome in MODELLI else next(iter(MODELLI)))
        self.luminosita = 1.0
        self.t0 = time.time()
        self.drag = None
        self.items = []  # (id_canvas, gruppo)

        self.win = self.crea_finestra_luce()
        self.crea_pannello()
        self.attiva_modello()
        self.aggiorna_luci()
        self.root.protocol("WM_DELETE_WINDOW", self.chiudi)

    # ---------- configurazione ----------
    def carica_config(self):
        try:
            with open(CONFIG, encoding="utf-8") as f:
                cfg = json.load(f)
            if isinstance(cfg, dict):
                return cfg
        except (OSError, ValueError):
            pass
        # posizione = punto di origine del CAD sullo schermo; scala = pixel per mm (stima iniziale)
        return {"x": 400, "y": 200, "scala": round(self.root.winfo_fpixels("1m"), 3), "colori": {}}

    def salva_config(self):
        self.cfg.update(modello=self.modello_var.get(), sfarfallio=self.sfarfallio.get(),
                        intensita=self.intensita.get(), bordo=self.bordo.get(),
                        effetto=self.effetto, ogni=self.ogni.get())
        try:
            os.makedirs(_CFG_DIR, exist_ok=True)
            with open(CONFIG, "w", encoding="utf-8") as f:
                json.dump(self.cfg, f, indent=2)
        except OSError:
            pass

    def colore(self, gruppo):
        return self.cfg["colori"].get(gruppo, COLORI_DEFAULT[gruppo])

    # ---------- pannello di controllo ----------
    def crea_pannello(self):
        r = self.root
        r.title(T("titolo"))
        r.geometry("360x760+60+150")
        r.attributes("-topmost", True)

        tk.Label(r, text=T("titolo"), font=("Arial", 13, "bold")).pack(pady=(8, 0))
        tk.Label(r, text="D3D Create by Dario  -  v" + VERSIONE, fg="#777").pack()

        fm = tk.LabelFrame(r, text=T("modello"), padx=10, pady=6)
        fm.pack(fill="x", padx=15, pady=4)
        tk.OptionMenu(fm, self.modello_var, *MODELLI.keys(), command=lambda _: self.attiva_modello()).pack(fill="x")
        tk.Checkbutton(fm, text=T("guida"), variable=self.mostra_guida,
                       command=self.ridisegna).pack(anchor="w")

        fc = tk.LabelFrame(r, text=T("comandi"), padx=10, pady=6)
        fc.pack(fill="x", padx=15, pady=4)
        tk.Label(fc, justify="left", text=T("aiuto")).pack(anchor="w")
        tk.Scale(fc, from_=0, to=BORDO_MAX, resolution=0.5, orient="horizontal", label=T("bordo"),
                 variable=self.bordo, command=lambda _: self.ridisegna()).pack(fill="x")

        fcol = tk.LabelFrame(r, text=T("colori"), padx=10, pady=6)
        fcol.pack(fill="x", padx=15, pady=4)
        self.btn_colori = {}
        for gruppo in ("occhi", "bocca"):
            riga = tk.Frame(fcol)
            riga.pack(fill="x", pady=2)
            tk.Label(riga, text=T(gruppo) + ":", width=12, anchor="w").pack(side="left")
            b = tk.Button(riga, text=T("scegli"), bg=self.colore(gruppo),
                          command=lambda g=gruppo: self.cambia_colore(g))
            b.pack(side="right", fill="x", expand=True)
            self.btn_colori[gruppo] = b

        fe = tk.LabelFrame(r, text=T("effetto"), padx=10, pady=6)
        fe.pack(fill="x", padx=15, pady=4)
        tk.OptionMenu(fe, self.effetto_var, *[T(e) for e in EFFETTI], command=self.cambia_effetto).pack(fill="x")
        tk.Scale(fe, from_=5, to=120, resolution=5, orient="horizontal", label=T("ogni"),
                 variable=self.ogni).pack(fill="x")
        tk.Checkbutton(fe, text=T("sfarfallio"), variable=self.sfarfallio).pack(anchor="w")
        tk.Scale(fe, from_=0, to=100, orient="horizontal", label=T("intensita"),
                 variable=self.intensita).pack(fill="x")

        tk.Button(r, text=T("riduci"), command=r.iconify).pack(pady=(8, 2), fill="x", padx=15)
        tk.Button(r, text=T("chiudi"), bg="#CC3333", fg="white", command=self.chiudi).pack(pady=4, fill="x", padx=15)

    # ---------- finestra delle luci ----------
    def crea_finestra_luce(self):
        win = tk.Toplevel(self.root)
        win.overrideredirect(True)
        win.attributes("-topmost", True)
        win.configure(bg=TRASPARENTE)
        try:
            win.attributes("-transparentcolor", TRASPARENTE)  # solo Windows
        except tk.TclError:
            pass
        self.canvas = tk.Canvas(win, bg=TRASPARENTE, highlightthickness=0, cursor="fleur")
        self.canvas.pack(fill="both", expand=True)
        self.canvas.bind("<Button-1>", lambda e: self.inizio(e, "sposta"))
        self.canvas.bind("<B1-Motion>", self.muovi)
        self.canvas.bind("<Button-3>", lambda e: self.inizio(e, "scala"))
        self.canvas.bind("<B3-Motion>", self.muovi)
        for tasto, dx, dy in (("Left", -1, 0), ("Right", 1, 0), ("Up", 0, -1), ("Down", 0, 1)):
            win.bind("<%s>" % tasto, lambda e, dx=dx, dy=dy: self.sposta(dx, dy))
        return win

    def attiva_modello(self):
        m = MODELLI[self.modello_var.get()]
        self.contorno = punti(m["contorno"])
        self.luci = [(l["g"], punti(l["p"])) for l in m["luci"]]
        xs = [p[0] for p in self.contorno]
        ys = [p[1] for p in self.contorno]
        m = BORDO_MAX + 1  # mm di margine della finestra
        self.mm_min = (min(xs) - m, min(ys) - m)   # angolo in alto a sinistra rispetto all'origine
        self.mm_dim = (max(xs) - min(xs) + 2 * m, max(ys) - min(ys) + 2 * m)
        self.ridisegna()

    def ridisegna(self):
        k = self.cfg["scala"]
        ox, oy = self.mm_min
        w, h = int(self.mm_dim[0] * k) + 2, int(self.mm_dim[1] * k) + 2
        x = int(self.cfg["x"] + ox * k)
        y = int(self.cfg["y"] + oy * k)
        self.win.geometry("{}x{}+{}+{}".format(w, h, x, y))

        def coord(pts):
            out = []
            for px, py in pts:
                out += [(px - ox) * k, (py - oy) * k]
            return out

        c = self.canvas
        c.delete("all")
        self.items = []
        # il bordo extra e' un contorno arrotondato dello stesso colore: la linea e' centrata
        # sul bordo del foro, quindi sporge all'esterno di meta' spessore
        spessore = 2 * self.bordo.get() * k
        for gruppo, pts in self.luci:
            if gruppo == "isola":
                pid = c.create_polygon(coord(pts), fill=TRASPARENTE, outline="")
            else:
                col = self.colore(gruppo)
                pid = c.create_polygon(coord(pts), fill=col, outline=col if spessore >= 1 else "",
                                       width=max(1, spessore), joinstyle="round")
            self.items.append((pid, gruppo))
        # le isole vanno sopra le luci (il bordo extra non deve coprirle)
        for pid, gruppo in self.items:
            if gruppo == "isola":
                c.tag_raise(pid)
        if self.mostra_guida.get():
            c.create_polygon(coord(self.contorno), fill="", outline="#FFFFFF", width=2, dash=(6, 4))

    # ---------- interazione ----------
    def inizio(self, e, modo):
        self.win.focus_force()
        self.drag = {"modo": modo, "x0": e.x_root, "y0": e.y_root,
                     "x": self.cfg["x"], "y": self.cfg["y"], "scala": self.cfg["scala"]}

    def muovi(self, e):
        if not self.drag:
            return
        dx, dy = e.x_root - self.drag["x0"], e.y_root - self.drag["y0"]
        if self.drag["modo"] == "sposta":
            self.cfg["x"], self.cfg["y"] = self.drag["x"] + dx, self.drag["y"] + dy
        else:
            larghezza = self.mm_dim[0] * self.drag["scala"]
            self.cfg["scala"] = round(self.drag["scala"] * max(30, larghezza + dx) / larghezza, 3)
        self.ridisegna()

    def sposta(self, dx, dy):
        self.cfg["x"] += dx
        self.cfg["y"] += dy
        self.ridisegna()

    def cambia_colore(self, gruppo):
        scelto = colorchooser.askcolor(initialcolor=self.colore(gruppo), parent=self.root)
        if scelto and scelto[1]:
            self.cfg["colori"][gruppo] = scelto[1]
            self.btn_colori[gruppo].config(bg=scelto[1])

    def cambia_effetto(self, etichetta):
        self.effetto = next(e for e in EFFETTI if T(e) == etichetta)
        self.t0 = time.time()

    # ---------- effetti luce ----------
    def colori_base(self, t):
        """Colori (r, g, b) di occhi e bocca in questo istante, secondo l'effetto scelto."""
        occhi, bocca = self.colore("occhi"), self.colore("bocca")
        periodo = max(5, self.ogni.get())
        if self.effetto == "cambio":
            n = int(t // periodo)
            dentro = t - n * periodo
            a, b = PALETTE[n % len(PALETTE)], PALETTE[(n + 1) % len(PALETTE)]
            f = max(0.0, (dentro - (periodo - DISSOLVENZA)) / DISSOLVENZA)  # dissolvenza a fine periodo
            return {"occhi": mescola(a[0], b[0], f), "bocca": mescola(a[1], b[1], f)}
        if self.effetto == "arcobaleno":
            h = (t / periodo) % 1.0
            return {g: tuple(v * 255 for v in colorsys.hsv_to_rgb((h + off) % 1.0, 1, 1))
                    for g, off in (("occhi", 0.0), ("bocca", 0.12))}
        rgb = {"occhi": hex_to_rgb(occhi), "bocca": hex_to_rgb(bocca)}
        if self.effetto == "respiro":
            # pulsazione lenta (circa 5 secondi), senza mai spegnersi del tutto
            lum = 0.6 + 0.4 * (0.5 + 0.5 * math.sin(2 * math.pi * t / 5.0))
            rgb = {g: tuple(v * lum for v in c) for g, c in rgb.items()}
        return rgb

    def aggiorna_luci(self):
        i = self.intensita.get() / 100.0
        if self.sfarfallio.get() and i > 0:
            # tremolio morbido: la luminosita' scivola verso un valore casuale, senza lampi
            obiettivo = random.uniform(1 - 0.45 * i, 1 + 0.08 * i)
            self.luminosita += (obiettivo - self.luminosita) * 0.35
        else:
            self.luminosita = 1.0
        base = self.colori_base(time.time() - self.t0)
        con_bordo = self.bordo.get() > 0
        for pid, gruppo in self.items:
            if gruppo != "isola":
                col = rgb_to_hex(tuple(v * self.luminosita for v in base[gruppo]))
                self.canvas.itemconfig(pid, fill=col, outline=col if con_bordo else "")
        self.root.after(random.randint(70, 140), self.aggiorna_luci)

    def chiudi(self):
        self.salva_config()
        self.root.destroy()


def main():
    root = tk.Tk()
    if not MODELLI:
        root.withdraw()
        messagebox.showerror(T("titolo"), T("nessuno"))
        return
    if not os.path.exists(CONFIG):  # primo avvio: avviso luci
        root.withdraw()
        if not messagebox.askyesno(T("avviso_t"), T("avviso"), icon="warning"):
            root.destroy()
            return
        root.deiconify()
    ScreenTopper(root)
    root.mainloop()


if __name__ == "__main__":
    main()
